  if(key==L"System.Devices.Aep.ContainerId"&&p.Type()==T::Guid)put(d,L"containerId",normalizedContainer(guid(p.GetGuid())));
  if(key==L"System.Devices.Aep.IsConnected"&&p.Type()==T::Boolean){put(d,L"connected",p.GetBoolean());put(d,L"status",p.GetBoolean()?std::wstring(L"已连接 · Windows 蓝牙状态"):std::wstring(L"已配对 · 未连接"));if(!p.GetBoolean()&&d.HasKey(L"battery"))d.Remove(L"battery");}
