   w.Added([state=shared,transport](auto const&,Info const& info){try{auto d=record(std::wstring(info.Id()),std::wstring(info.Name()),L"peripheral",transport);put(d,L"status",std::wstring(L"已配对 · 连接状态未知"));for(auto const& p:info.Properties())property(d,std::wstring(p.Key()),p.Value());if(d.HasKey(L"connected")&&!flag(d,L"connected")&&d.HasKey(L"battery"))d.Remove(L"battery");std::lock_guard guard(state->lock);state->devices[std::wstring(info.Id())]=d;}catch(...) {}});
